theorem sigma_fun_on_range {ρ σ : X → X → Prop}
    (h : IsFun (relProd ρ σ)) :
    ∀ y, (∃ x, ρ x y) → ∀ z w, σ y z → σ y w → z = w

theorem relSub_relPow_succ {ρ σ : X → X → Prop}
    (hρσ : RelSub ρ σ) (hσ : TransRel σ) (n : Nat) :
    RelSub (relPow ρ (n+1)) σ

theorem relStar_least {ρ σ : X → X → Prop}
    (hρσ : RelSub ρ σ) (hσ : TransRel σ) (hrefl : ReflOn (Field ρ) σ) :
    RelSub (relStar ρ) σ

theorem pred_inter_range_nonempty {ρ : X → X → Prop} {a : Nat → X}
    (hd : InfDesc ρ a) :
    ∀ x, x ∈ range a → ∃ y, y ∈ predR ρ x ∩ range a

theorem pred_inter_range_ne_empty {ρ : X → X → Prop} {a : Nat → X}
    (hd : InfDesc ρ a) :
    ∀ x, x ∈ range a → predR ρ x ∩ range a ≠ ∅

theorem exists_step {ρ : X → X → Prop} {B : Set X}
    (hB : ∀ x, x ∈ B → ∃ y, y ∈ B ∧ ρ y x) :
    ∃ f : {x // x ∈ B} → {x // x ∈ B}, ∀ x, ρ (f x).1 x.1
